<script setup lang="ts">
import ImportPanel from './ImportPanel.vue';
import ImportOriginPanel from '../components/ImportOriginPanel.vue';
import CampusPanel from './CampusPanel.vue';
import CatalogPanel from './CatalogPanel.vue';
import { ref, computed, onBeforeUnmount } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { adminServices } from '../services/AdminServices';
import { CampusRole, type CampusSession, FeedbackStatus, type PendingReviewItem, type ContestVersion, type Feedback, type ContestPayload, type AuditLog, type Publicity, type ImportDraftReview } from '../models/contracts';
import { fieldLabel } from '../services/ContestDetailService';
const session=adminServices.getSession();
const importPanel=ref<InstanceType<typeof ImportPanel>|null>(null),importBusy=ref(false),importTarget=ref(''),catalogTarget=ref(''),importOrigin=ref<ImportDraftReview|null>(null),importOriginError=ref('');
async function beforeTabChange(next:string|number,previous:string|number){return previous==='imports'&&next!=='imports'&&importPanel.value?await importPanel.value.canLeave():true;}
function startImport(id:string){importTarget.value=id;tab.value='imports';}
function openImportedDraft(id:string){catalogTarget.value=id;tab.value='catalog';}
const authorization=ref<CampusSession|null>(null),activeSchool=ref('');
function workspace(){const a=authorization.value;if(!a)return;const scopes=a.members.filter(m=>m.role===CampusRole.Value1||m.role===CampusRole.Value2).map(m=>m.schoolId).filter((id):id is string=>!!id);if(!scopes.includes(activeSchool.value))activeSchool.value=scopes.includes(a.schoolId)?a.schoolId:scopes[0]||'';adminServices.setManagementSchool(activeSchool.value||null);}
async function switchSchool(next:string){if(tab.value==='imports'&&importPanel.value&&!await importPanel.value.canLeave())return;detailGeneration++;detailOpen.value=false;selected.value=null;importOrigin.value=null;importOriginError.value='';activeSchool.value=next;importTarget.value='';catalogTarget.value='';adminServices.setManagementSchool(activeSchool.value||null);tab.value=schoolAdmin.value?'review':maintainer.value?'catalog':'campus';await load(1);}
const schoolAdmin=computed(()=>authorization.value?.members.some(m=>m.role===CampusRole.Value1&&m.schoolId===activeSchool.value)||false);
const campusManager=computed(()=>authorization.value?.members.some(m=>m.role===CampusRole.Value0||m.role===CampusRole.Value1)||false);
const maintainer=computed(()=>schoolAdmin.value||authorization.value?.members.some(m=>m.role===CampusRole.Value2&&m.schoolId===activeSchool.value)||false);
async function refreshCampus(){try{authorization.value=await adminServices.getCampus().me();workspace();}catch(e){session.invalidate();authenticated.value=false;authorization.value=null;adminServices.setManagementSchool(null);activeSchool.value='';error.value=message(e);}}
const account=ref('admin'),password=ref(''),authenticated=ref(false),loginBusy=ref(false),error=ref('');
const tab=ref('review'),busy=ref(false),page=ref(1),total=ref(0),keyword=ref(''),status=ref<FeedbackStatus|''>('');
const pending=ref<PendingReviewItem[]>([]),feedback=ref<Feedback[]>([]);
const pendingPublicity=ref<Publicity[]>([]),selectedPublicity=ref<Publicity|null>(null),publicityOpen=ref(false),publicityReason=ref('');
const selected=ref<PendingReviewItem|null>(null),version=ref<ContestVersion|null>(null),published=ref<ContestVersion|null>(null),logs=ref<AuditLog[]>([]),detailOpen=ref(false),detailBusy=ref(false),reason=ref('');
const selectedFeedback=ref<Feedback|null>(null),feedbackOpen=ref(false),handleStatus=ref(FeedbackStatus.Value2),note=ref('');
let generation=0,detailGeneration=0,alive=true;
onBeforeUnmount(()=>{alive=false;generation++;detailGeneration++;});
function message(e:unknown):string{return e instanceof Error?e.message:'操作失败，请重试';}
async function guard():Promise<boolean>{if(await session.check()){try{authorization.value=await adminServices.getCampus().me();workspace();return true;}catch(e){error.value=message(e);session.invalidate();}}authenticated.value=false;authorization.value=null;adminServices.setManagementSchool(null);activeSchool.value='';pending.value=[];feedback.value=[];pendingPublicity.value=[];selectedPublicity.value=null;detailOpen.value=false;feedbackOpen.value=false;publicityOpen.value=false;error.value='登录已失效，请重新登录';generation++;detailGeneration++;return false;}
async function login(){if(loginBusy.value)return;loginBusy.value=true;error.value='';try{await session.login({account:account.value.trim(),password:password.value});authorization.value=await adminServices.getCampus().me();workspace();authenticated.value=true;tab.value=schoolAdmin.value?'review':campusManager.value?'campus':'catalog';await load(1);}catch(e){error.value=message(e);try{await session.logout();}catch{}authenticated.value=false;authorization.value=null;adminServices.setManagementSchool(null);activeSchool.value='';}finally{password.value='';loginBusy.value=false;}}
async function logout(){if(tab.value==='imports'&&importPanel.value&&!await importPanel.value.canLeave())return;generation++;detailGeneration++;try{await session.logout();}catch(e){ElMessage.warning(message(e));}finally{authenticated.value=false;authorization.value=null;adminServices.setManagementSchool(null);activeSchool.value='';pending.value=[];feedback.value=[];pendingPublicity.value=[];selectedPublicity.value=null;selected.value=null;selectedFeedback.value=null;detailOpen.value=false;feedbackOpen.value=false;publicityOpen.value=false;busy.value=false;}}
async function load(next=page.value){const id=++generation;busy.value=true;error.value='';try{if(!(await guard()))return;if(tab.value==='catalog'||tab.value==='campus'||tab.value==='imports')return;if(tab.value==='review'){const result=await adminServices.getContests().listPending({keyword:keyword.value.trim(),page:next,pageSize:20});if(id!==generation||!alive)return;pending.value=result.list;total.value=result.total;}else if(tab.value==='publicity'){const result=await adminServices.getPublicity().listPending({page:next,pageSize:20});if(id!==generation||!alive)return;pendingPublicity.value=result.list;total.value=result.total;}else{const result=await adminServices.getFeedback().listManaged({status:status.value||undefined,page:next,pageSize:20});if(id!==generation||!alive)return;feedback.value=result.list;total.value=result.total;}page.value=next;}catch(e){if(id===generation)error.value=message(e);}finally{if(id===generation)busy.value=false;else if(!authenticated.value)busy.value=false;}}
async function open(row:PendingReviewItem){const id=++detailGeneration;detailOpen.value=true;detailBusy.value=true;selected.value=null;version.value=null;published.value=null;logs.value=[];reason.value='';importOrigin.value=null;importOriginError.value='';try{if(!(await guard()))return;const repository=adminServices.getContests();const values=await Promise.all([repository.getVersion(row.contestId,row.versionId),repository.getManaged(row.contestId),repository.getInternalAuditLog(row.contestId)]);if(id!==detailGeneration||!alive||!detailOpen.value)return;version.value=values[0];published.value=values[1].publishedVersion;logs.value=values[2];selected.value={...row,etag:values[0].etag};try{const source=await adminServices.getImports().getDraftReview(row.versionId);if(id===detailGeneration&&alive&&detailOpen.value)importOrigin.value=source;}catch(e){if(id===detailGeneration)importOriginError.value=message(e);}}catch(e){ElMessage.error(message(e));}finally{if(id===detailGeneration)detailBusy.value=false;}}
async function review(approve:boolean){if(busy.value||detailBusy.value||!selected.value||!version.value)return;if(!approve&&!reason.value.trim()){ElMessage.warning('请填写驳回原因');return;}const row={...selected.value};busy.value=true;try{await ElMessageBox.confirm(approve?'通过后，该版本将替换当前公开版本。':'确认驳回该版本？旧公开版本继续保留。','确认审核',{confirmButtonText:approve?'通过审核':'驳回',cancelButtonText:'取消',type:'warning'});}catch{busy.value=false;return;}try{if(!(await guard()))return;const repository=adminServices.getContests();if(approve)await repository.reviewApprove(row.contestId,{versionId:row.versionId,etag:row.etag});else await repository.reviewReject(row.contestId,{versionId:row.versionId,etag:row.etag,rejectReason:reason.value.trim()});detailOpen.value=false;selected.value=null;ElMessage.success(approve?'已通过并切换公开版本':'已驳回，旧公开版本保留');await load(1);}catch(e){ElMessage.error(message(e));selected.value=null;detailOpen.value=false;await load(page.value);}finally{busy.value=false;}}
async function reviewPublicity(approve:boolean){if(busy.value||!selectedPublicity.value)return;if(!approve&&!publicityReason.value.trim()){ElMessage.warning('请填写驳回原因');return;}const row={...selectedPublicity.value};busy.value=true;try{await ElMessageBox.confirm(approve?'通过并更新当前公开公示？':'驳回后保留原公开公示。','确认公示审核');}catch{busy.value=false;return;}try{if(!(await guard()))return;const repository=adminServices.getPublicity();if(approve)await repository.reviewApprove(row.id,{ifMatch:row.etag});else await repository.reviewReject(row.id,{rejectReason:publicityReason.value.trim()},{ifMatch:row.etag});publicityOpen.value=false;ElMessage.success(approve?'公示已通过':'公示已驳回');await load(1);}catch(e){ElMessage.error(message(e));publicityOpen.value=false;await load(page.value);}finally{busy.value=false;}}
function fields(payload:ContestPayload){return Object.keys(payload) as (keyof ContestPayload)[];}
function value(input:unknown){return input===null||input===undefined||input===''?'未公布':typeof input==='object'?JSON.stringify(input):String(input);}
function openFeedback(row:Feedback){selectedFeedback.value={...row};handleStatus.value=FeedbackStatus.Value2;note.value='';feedbackOpen.value=true;}
async function handle(){if(busy.value||!selectedFeedback.value)return;if(!note.value.trim()){ElMessage.warning('请填写处理说明');return;}busy.value=true;try{if(!(await guard()))return;await adminServices.getFeedback().handle(selectedFeedback.value.id,{status:handleStatus.value,note:note.value.trim()});feedbackOpen.value=false;ElMessage.success('处理结果已保存，学生可查看说明');await load(1);}catch(e){ElMessage.error(message(e));feedbackOpen.value=false;await load(page.value);}finally{busy.value=false;}}
</script>
<template>
 <main class="review-shell">
  <header><div><h1>竞知 · 审核工作台</h1><p>高校管理与赛事维护 · 共享后端</p></div><el-button v-if="authenticated" @click="logout" :disabled="busy||importBusy">退出登录</el-button></header>
  <el-alert title="数据保存至后端数据库，刷新后需重新登录。平台审核不代表学校官方认证。" type="info" :closable="false" />
  <el-alert v-if="error" :title="error" type="error" :closable="false" class="space" />
  <el-card v-if="!authenticated" class="login-card">
   <h2>管理人员登录</h2><el-form @submit.prevent="login" label-position="top"><el-form-item label="账号"><el-input v-model="account" :disabled="loginBusy" autocomplete="username" /></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password :disabled="loginBusy" autocomplete="off" /></el-form-item><el-button native-type="submit" type="primary" :loading="loginBusy" :disabled="!account.trim()||!password">登录</el-button></el-form><p>使用已有校级管理员、平台管理员或学院负责人的账号；账号必须具有有效授权。</p>
  </el-card>
  <template v-else>
   <el-select v-if="authorization?.schools.length"  :model-value="activeSchool" :disabled="importBusy" class="space" placeholder="当前赛事工作高校" @change="switchSchool"><el-option v-for="s in authorization.schools" :key="s.id" :label="s.name" :value="s.id"/></el-select>
   <el-tabs v-model="tab" :before-leave="beforeTabChange" class="space" @tab-change="load(1)">
    <el-tab-pane v-if="campusManager" label="高校管理" name="campus" /><el-tab-pane v-if="maintainer" label="赛事维护 / 目录编辑" name="catalog" /><el-tab-pane v-if="maintainer" label="文件导入" name="imports" /><el-tab-pane v-if="schoolAdmin" label="赛事审核" name="review" /><el-tab-pane v-if="schoolAdmin" label="公示审核" name="publicity" /><el-tab-pane v-if="schoolAdmin" label="反馈处理" name="feedback" />
   </el-tabs>
   <CampusPanel v-if="tab==='campus'&&authorization" :authorization="authorization" @changed="refreshCampus" @session-expired="guard" />
   <CatalogPanel :key="activeSchool" v-if="tab==='catalog'" :open-contest-id="catalogTarget" @import-file="startImport" @session-expired="guard" />
   <ImportPanel v-if="tab==='imports'&&maintainer" ref="importPanel" :key="activeSchool" :school-id="activeSchool" :school-admin="schoolAdmin" :initial-target-id="importTarget" @busy="importBusy=$event" @open-draft="openImportedDraft" @session-expired="guard" />
   <template v-if="tab!=='catalog'&&tab!=='campus'&&tab!=='imports'">
   <section class="toolbar"><el-input v-if="tab==='review'" v-model="keyword" placeholder="搜索赛事名称" clearable @keyup.enter="load(1)" style="max-width:320px" /><el-select v-else-if="tab==='feedback'" v-model="status" placeholder="全部反馈状态" clearable style="width:200px" @change="load(1)"><el-option v-for="s in Object.values(FeedbackStatus)" :key="s" :label="s" :value="s" /></el-select><el-button @click="load(1)" :loading="busy">查询 / 刷新</el-button><span>共 {{total}} 条</span></section>
   <el-table v-if="tab==='review'" :data="pending" v-loading="busy" empty-text="暂无待审核赛事">
    <el-table-column prop="name" label="赛事" min-width="220" /><el-table-column prop="organizationName" label="单位" min-width="160" /><el-table-column prop="submittedAt" label="提交时间" min-width="200" /><el-table-column label="待补充" width="100"><template #default="{row}">{{row.incompleteFields.length}} 项</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button type="primary" link @click="open(row)" :disabled="busy">查看审核</el-button></template></el-table-column>
   </el-table>
   <el-table v-else-if="tab==='publicity'" :data="pendingPublicity" v-loading="busy" empty-text="暂无待审核公示"><el-table-column prop="contestId" label="赛事" /><el-table-column prop="type" label="类型" /><el-table-column prop="versionNo" label="版本" /><el-table-column prop="reason" label="修改原因" /><el-table-column label="操作"><template #default="{row}"><el-button type="primary" link :disabled="busy" @click="selectedPublicity={...row};publicityReason='';publicityOpen=true">查看审核</el-button></template></el-table-column></el-table>
   <el-table v-else :data="feedback" v-loading="busy" empty-text="暂无反馈">
    <el-table-column prop="type" label="类型" width="100" /><el-table-column prop="desc" label="反馈内容" min-width="260" /><el-table-column prop="contestId" label="赛事" width="110" /><el-table-column prop="status" label="状态" width="100" /><el-table-column prop="note" label="处理说明" min-width="180" /><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" @click="openFeedback(row)" :disabled="busy||row.status===FeedbackStatus.Value2||row.status===FeedbackStatus.Value3">处理</el-button></template></el-table-column>
   </el-table>
   <el-pagination class="space" background layout="prev, pager, next, total" :total="total" :page-size="20" :current-page="page" :disabled="busy" @current-change="load" />
   </template>
  </template>
  <el-dialog v-model="detailOpen" title="审核版本与公开版本对比" width="90%" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" @closed="detailGeneration++">
   <div v-loading="detailBusy"><template v-if="version">
    <p>版本 {{version.versionNo}} · {{version.status}} · 修改原因：{{version.reason || '首次提交'}}</p>
    <el-alert v-if="selected?.incompleteFields.length" :title="'待补充：'+selected.incompleteFields.map(fieldLabel).join('、')" type="warning" :closable="false" />
    <el-alert v-if="importOriginError" :title="'文件来源读取失败：'+importOriginError+'；请重新打开后再审核。'" type="error" :closable="false"/>
    <ImportOriginPanel v-if="importOrigin" :review="importOrigin" :school-id="activeSchool" @session-expired="guard"/>
    <p v-if="!published">首次发布，当前没有公开版本。</p>
    <el-table :data="fields(version.payload).map(field=>({field,old:published?.payload[field],new:version!.payload[field]}))" max-height="420">
     <el-table-column label="字段" width="160"><template #default="{row}">{{fieldLabel(row.field)}}</template></el-table-column><el-table-column label="当前公开版本" min-width="200"><template #default="{row}">{{value(row.old)}}</template></el-table-column><el-table-column label="待审版本" min-width="200"><template #default="{row}"><span :class="{'changed':JSON.stringify(row.old)!==JSON.stringify(row.new)}">{{value(row.new)}}</span></template></el-table-column>
    </el-table>
    <el-collapse class="space"><el-collapse-item title="内部修改及审核记录（仅后台）"><el-table :data="logs"><el-table-column prop="time" label="时间" min-width="180" /><el-table-column prop="operator" label="操作者" /><el-table-column prop="field" label="字段" /><el-table-column prop="reason" label="原因" /></el-table></el-collapse-item></el-collapse>
    <el-input v-model="reason" type="textarea" placeholder="驳回原因必填，通过无需填写" maxlength="2000" show-word-limit :disabled="busy" />
   </template></div>
   <template #footer><el-button @click="detailOpen=false" :disabled="busy">关闭</el-button><el-button type="danger" @click="review(false)" :disabled="busy||detailBusy||!selected||!reason.trim()">驳回</el-button><el-button type="primary" @click="review(true)" :disabled="busy||detailBusy||!selected||!!importOriginError">通过审核</el-button></template>
  </el-dialog>
  <el-dialog v-model="publicityOpen" title="公示审核" width="min(800px,90%)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><p>赛事：{{selectedPublicity?.contestId}} · {{selectedPublicity?.type}} · 版本 {{selectedPublicity?.versionNo}}</p><p>修改原因：{{selectedPublicity?.reason}}</p><pre class="publicity-content">{{typeof selectedPublicity?.content==='string'?selectedPublicity.content:JSON.stringify(selectedPublicity?.content,null,2)}}</pre><el-input v-model="publicityReason" type="textarea" placeholder="驳回原因必填" maxlength="2000" :disabled="busy" /><template #footer><el-button @click="publicityOpen=false" :disabled="busy">关闭</el-button><el-button type="danger" @click="reviewPublicity(false)" :disabled="busy||!publicityReason.trim()">驳回</el-button><el-button type="primary" @click="reviewPublicity(true)" :disabled="busy">通过公示</el-button></template></el-dialog>
  <el-dialog v-model="feedbackOpen" title="处理学生反馈" width="min(640px,90%)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy">
   <p>{{selectedFeedback?.desc}}</p><el-select v-model="handleStatus" :disabled="busy"><el-option v-for="s in [FeedbackStatus.Value1,FeedbackStatus.Value2,FeedbackStatus.Value3]" :key="s" :label="s" :value="s" /></el-select><el-input class="space" v-model="note" type="textarea" placeholder="填写学生可见的处理说明" maxlength="2000" show-word-limit :disabled="busy" /><template #footer><el-button @click="feedbackOpen=false" :disabled="busy">取消</el-button><el-button type="primary" @click="handle" :disabled="busy||!note.trim()" :loading="busy">保存处理结果</el-button></template>
  </el-dialog>
 </main>
</template>
<style scoped>
.publicity-content{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;background:#f5f7fa;padding:16px}.review-shell{max-width:1280px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}h1{font-size:26px;margin:0}header p{color:#64748b}.space{margin-top:20px}.toolbar{display:flex;gap:12px;align-items:center;margin:16px 0}.login-card{max-width:480px;margin:48px auto}.changed{color:#b54708;white-space:pre-wrap}.el-table{border-radius:10px}@media(max-width:640px){.publicity-content{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;background:#f5f7fa;padding:16px}.review-shell{padding:14px}.toolbar{flex-wrap:wrap}h1{font-size:20px}}
</style>
